#[no_mangle]
pub unsafe extern "C" fn tsvc_s242_fused_prefix_update(p:*const f64,l:usize,q:*mut f64,cap:usize)->i64{if p.is_null()||l<7||l>259{return -1}let x=unsafe{std::slice::from_raw_parts(p,l)};let r=x[0];if !r.is_finite()||r.fract()!=0.0||r<1.0||r>64.0{return -1}let n=r as usize;if l!=3+4*n||x[1..].iter().any(|v|!v.is_finite()||v.fract()!=0.0||v.abs()>1.0){return -1}if q.is_null()||cap<n{return -2}let mut a=[0.0;64];a[..n].copy_from_slice(&x[3..3+n]);for i in 1..n{let mut v=a[i-1]+x[1];v+=x[2];v+=x[3+2*n+i];v+=x[3+3*n+i];v+=x[3+4*n+i];a[i]=v}let y=unsafe{std::slice::from_raw_parts_mut(q,n)};y.copy_from_slice(&a[..n]);n as i64}
